        {
            if (!IsEnabled) return 0.0;
            double result = (BaseMagnitude * MultiplierValue) + (inputVal * scalingFactor * 1.25);
            if (applyBonus)
            {
                result *= 1.35;
                result += LevelTier * 4.5;
